with with_windows as (select id, account_id, txn_type, amount, txn_time, merchant, is_flagged, count(amount) over (partition by merchant, account_id) as merchant_count_amount, lag(amount, 1) over (partition by account_id order by amount, id) as prev_amount, round(amount / sum(amount) over (partition by merchant), 4) as amount_share, avg(amount) over (partition by account_id order by txn_time, id rows between 6 preceding and 1 preceding) as amount_avg_6_prior, lead(amount, 1) over (partition by merchant order by txn_time, id) as next_amount from transactions) select s.id, s.account_id, s.txn_type, s.amount, s.merchant, s.merchant_count_amount, s.amount_avg_6_prior, s.next_amount, (select sum(t2.amount) from transactions t2 where t2.account_id = s.account_id) as sum_transaction_amount from with_windows s
